SELECT 
FROM flow_instance i
WHERE 1 = 1
  AND /* @dataScope(table=flow_instance, alias=i) */

  AND i.template_id = #{templateId}


  AND i.template_version = #{templateVersion}


  AND i.status = #{status}


  AND i.initiator_id = #{initiatorId}

ORDER BY i.id DESC

  LIMIT #{limit}

mapper.update:
UPDATE flow_instance
SET current_node_seq = #{currentNodeSeq}, updated_at = NOW()
WHERE id = #{id}
